package net.civeira.phylax.features.notification.message.infrastructure.event;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Event;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.features.notification.message.domain.Message;
import net.civeira.phylax.features.notification.message.domain.event.MessageEvent;

@ApplicationScoped
@RequiredArgsConstructor
public class MessageEventDispatcher {

  /**
   * @autogenerated EventDispatcherGenerator
   */
  private final Event<MessageEvent> emitter;

  /**
   * @autogenerated EventDispatcherGenerator
   * @param entity
   */
  public void dispatch(final Message entity) {
    entity.getRecordedEvents().forEach(emitter::fire);
  }
}
